namespace RecipeShare.Models;

public class Recipe
{
    public int Id { get; set; }
    public string Title { get; set; } = string.Empty;
    public string Category { get; set; } = string.Empty;
    public string Ingredients { get; set; } = string.Empty;
    public string Steps { get; set; } = string.Empty;
    public List<int> Ratings { get; set; } = [];

    public double AverageRating => Ratings.Count > 0
        ? Math.Round(Ratings.Average(), 1)
        : 0;
}

using RecipeShare.Models;

namespace RecipeShare.Services;

public class RecipeService
{
    private readonly List<Recipe> _recipes =
    [
        new()
        {
            Id = 1, Title = "Classic Margherita Pizza", Category = "Italian",
            Ingredients = "Pizza dough\nSan Marzano tomatoes\nFresh mozzarella\nFresh basil\nOlive oil\nSalt",
            Steps = "1. Preheat oven to 475°F (245°C).\n2. Roll out dough on a floured surface.\n3. Spread crushed tomatoes evenly.\n4. Tear mozzarella and distribute over sauce.\n5. Bake for 10-12 minutes until crust is golden.\n6. Top with fresh basil and drizzle with olive oil.",
            Ratings = [5, 4, 5, 4, 5]
        },
        new()
        {
            Id = 2, Title = "Spaghetti Carbonara", Category = "Italian",
            Ingredients = "Spaghetti\nGuanciale or pancetta\nEgg yolks\nPecorino Romano\nBlack pepper",
            Steps = "1. Cook spaghetti in salted water until al dente.\n2. Crisp guanciale in a pan.\n3. Whisk egg yolks with grated Pecorino and pepper.\n4. Toss hot pasta with guanciale, remove from heat.\n5. Stir in egg mixture quickly to create a creamy sauce.\n6. Serve immediately with extra Pecorino.",
            Ratings = [5, 5, 4]
        },
        new()
        {
            Id = 3, Title = "Chicken Tikka Masala", Category = "Indian",
            Ingredients = "Chicken breast\nYogurt\nGaram masala\nTurmeric\nTomato sauce\nHeavy cream\nOnion\nGarlic\nGinger",
            Steps = "1. Marinate chicken in yogurt, garam masala, and turmeric for 1 hour.\n2. Grill or broil chicken until charred.\n3. Sauté onion, garlic, and ginger.\n4. Add tomato sauce and simmer 15 minutes.\n5. Stir in cream and add chicken pieces.\n6. Simmer 10 minutes and serve with rice or naan.",
            Ratings = [5, 4, 4, 5]
        },
        new()
        {
            Id = 4, Title = "Vegetable Pad Thai", Category = "Thai",
            Ingredients = "Rice noodles\nTofu\nBean sprouts\nScallions\nPeanuts\nLime\nFish sauce\nTamarind paste\nSugar\nChili flakes",
            Steps = "1. Soak rice noodles in warm water for 20 minutes.\n2. Press and cube tofu, pan-fry until golden.\n3. Make sauce: mix tamarind paste, fish sauce, and sugar.\n4. Stir-fry noodles with sauce until coated.\n5. Add tofu, bean sprouts, and scallions.\n6. Serve with crushed peanuts, lime wedges, and chili flakes.",
            Ratings = [4, 5, 4]
        },
        new()
        {
            Id = 5, Title = "Beef Tacos", Category = "Mexican",
            Ingredients = "Ground beef\nTaco seasoning\nCorn tortillas\nLettuce\nTomato\nCheddar cheese\nSour cream\nSalsa",
            Steps = "1. Brown ground beef and drain excess fat.\n2. Add taco seasoning with a splash of water, simmer 5 minutes.\n3. Warm tortillas in a dry skillet.\n4. Fill tortillas with seasoned beef.\n5. Top with shredded lettuce, diced tomato, cheese, sour cream, and salsa.",
            Ratings = [4, 4, 5, 3]
        },
        new()
        {
            Id = 6, Title = "Chocolate Lava Cake", Category = "Desserts",
            Ingredients = "Dark chocolate\nButter\nEggs\nSugar\nFlour\nVanilla extract",
            Steps = "1. Preheat oven to 425°F (220°C). Grease ramekins.\n2. Melt chocolate and butter together.\n3. Whisk eggs with sugar and vanilla.\n4. Fold chocolate mixture into eggs, then fold in flour.\n5. Pour into ramekins and bake 12-14 minutes.\n6. Invert onto plates and serve immediately.",
            Ratings = [5, 5, 5, 4, 5]
        },
        new()
        {
            Id = 7, Title = "Green Curry", Category = "Thai",
            Ingredients = "Green curry paste\nCoconut milk\nChicken or tofu\nBamboo shoots\nThai basil\nFish sauce\nSugar\nBell pepper",
            Steps = "1. Heat a tablespoon of coconut cream in a pot.\n2. Fry green curry paste for 2 minutes.\n3. Add coconut milk and bring to a simmer.\n4. Add protein and vegetables, cook 15 minutes.\n5. Season with fish sauce and sugar.\n6. Garnish with Thai basil and serve over jasmine rice.",
            Ratings = [4, 5]
        },
        new()
        {
            Id = 8, Title = "Guacamole", Category = "Mexican",
            Ingredients = "Avocados\nLime juice\nCilantro\nRed onion\nJalapeño\nTomato\nSalt\nGarlic",
            Steps = "1. Halve and pit avocados, scoop into a bowl.\n2. Mash to desired consistency.\n3. Stir in diced onion, jalapeño, tomato, and cilantro.\n4. Add lime juice, minced garlic, and salt.\n5. Taste and adjust seasoning.\n6. Serve with tortilla chips.",
            Ratings = [5, 4, 5]
        }
    ];

    private int _nextId = 9;

    public IReadOnlyList<Recipe> GetAll() => _recipes.AsReadOnly();

    public List<string> GetCategories() =>
        _recipes.Select(r => r.Category).Distinct().OrderBy(c => c).ToList();

    public List<Recipe> GetByCategory(string category) =>
        _recipes.Where(r => r.Category.Equals(category, StringComparison.OrdinalIgnoreCase)).ToList();

    public Recipe? GetById(int id) => _recipes.FirstOrDefault(r => r.Id == id);

    public void AddRecipe(Recipe recipe)
    {
        recipe.Id = _nextId++;
        _recipes.Add(recipe);
    }

    public void AddRating(int recipeId, int stars)
    {
        var recipe = GetById(recipeId);
        if (recipe is not null && stars is >= 1 and <= 5)
        {
            recipe.Ratings.Add(stars);
        }
    }
}

