    @for (int i = 1; i <= 5; i++)
    {
        var star = i;
        <button class="btn btn-link p-0 fs-4 text-decoration-none"
                style="@(star <= selectedRating ? "color: gold;" : "color: #ccc;")"
                @onclick="() => Rate(star)"
                disabled="@submitted"
                title="@($"Rate {star} star{(star > 1 ? "s" : "")}")">
